from rdkit import Chem
from rdkit.Chem import AllChem
from rdkit.Geometry import Point3D
import numpy as np
ls=open('initial.xyz').read().splitlines();sym=[l.split()[0] for l in ls[2:]];x=np.array([list(map(float,l.split()[1:])) for l in ls[2:]])
m=Chem.MolFromMolFile('ligand_compressed.mol',removeHs=False)
for i in range(74):m.GetConformer().SetAtomPosition(i,Point3D(*x[i]))
ff=AllChem.MMFFGetMoleculeForceField(m,AllChem.MMFFGetMoleculeProperties(m))
for j in range(74,85):
 k=ff.AddExtraPoint(*x[j],fixed=True)-1
 assert k==j,(k,j)
 for i in range(74):
  if j==74:
   if i in [8,25]: ff.AddDistanceConstraint(i,k,2.34,2.34,100)
   elif i in [7,9,15,24,26,32]:ff.AddDistanceConstraint(i,k,3.35,3.7,40)
   else:ff.AddDistanceConstraint(i,k,2.25 if sym[i]=='H' else 2.9,100,10)
  else:
   rad={'C':1.7,'P':1.8,'O':1.52,'H':1.2}
   lower=.85*(rad[sym[i]]+rad[sym[j]])
   ff.AddDistanceConstraint(i,k,lower,100,10)
ff.Initialize();print('before',ff.CalcEnergy());print(ff.Minimize(maxIts=3000));print('after',ff.CalcEnergy())
x[:74]=m.GetConformer().GetPositions()
with open('preopt.xyz','w') as f:
 f.write('85\nXantphos palladium benzyne complex with all hydrogens\n')
 for s,pos in zip(sym,x):f.write(f'{s:2} {pos[0]: .8f} {pos[1]: .8f} {pos[2]: .8f}\n')
